use crate::cost::Mode;
use crate::grid::Grid;
use crate::localize::{SimRequest, simulate};
use crate::params::{MissionParams, encode_u8};
use crate::planner::{Obstacle, PlanError, Planner};
use crate::world::World;
use serde::Deserialize;
use serde_json::{Value, json};

#[derive(Debug)]
pub enum EngineError {
    Plan(PlanError),
    UnknownLayer(String),
}

impl From<PlanError> for EngineError {
    fn from(e: PlanError) -> Self {
        Self::Plan(e)
    }
}

impl EngineError {
    /// (HTTP 狀態碼, 錯誤代碼, 訊息)
    pub fn describe(&self) -> (u16, &'static str, String) {
        match self {
            Self::Plan(PlanError::OutOfBounds) => {
                (400, "out_of_bounds", "coordinate outside the map".into())
            }
            Self::Plan(PlanError::Blocked) => (
                422,
                "blocked",
                "start or goal is inside a hazard area".into(),
            ),
            Self::Plan(PlanError::NoPath) => (422, "no_path", "no traversable route found".into()),
            Self::UnknownLayer(n) => (404, "unknown_layer", format!("layer '{n}' not available")),
        }
    }
    pub fn to_json(&self) -> Value {
        let (_, code, msg) = self.describe();
        json!({"error": code, "message": msg})
    }
}

/// 二進位網格輸出（u8 或 f32 的位元組）。
pub struct GridBytes {
    pub w: usize,
    pub h: usize,
    pub cell_m: f32,
    pub bytes: Vec<u8>,
}

#[derive(Debug, Default, Deserialize)]
pub struct LayerQuery {
    pub step: Option<usize>,
    pub mode: Option<Mode>,
    pub x: Option<f32>,
    pub y: Option<f32>,
    pub o2_min: Option<f32>,
}

#[derive(Debug, Deserialize)]
pub struct RouteReq {
    pub start: [f32; 2],
    pub goal: [f32; 2],
    pub mode: Option<Mode>,
}

#[derive(Debug, Deserialize)]
pub struct ReplanReq {
    pub pos: [f32; 2],
    pub goal: [f32; 2],
    pub mode: Option<Mode>,
    #[serde(default)]
    pub obstacles: Vec<Obstacle>,
    pub o2_min: Option<f32>,
}

#[derive(Debug, Deserialize)]
pub struct TrackReq {
    pub pos: [f32; 2],
    pub sigma_m: Option<f32>,
    pub path: Vec<[f32; 3]>,
    pub lookahead_m: Option<f32>,
}

pub struct Engine {
    pub world: World,
    pub planner: Planner,
}

fn u8_grid(g: &Grid<f32>, step: usize, min: f32, max: f32) -> GridBytes {
    let d = g.downsample(step);
    GridBytes {
        w: d.w,
        h: d.h,
        cell_m: d.cell_m,
        bytes: d.data.iter().map(|&v| encode_u8(v, min, max)).collect(),
    }
}

fn bool_grid(g: &Grid<bool>, step: usize) -> GridBytes {
    let d = g.downsample(step);
    GridBytes {
        w: d.w,
        h: d.h,
        cell_m: d.cell_m,
        bytes: d.data.iter().map(|&b| if b { 255 } else { 0 }).collect(),
    }
}

impl Engine {
    pub fn new(world: World) -> Self {
        let planner = Planner::new(&world, MissionParams::default());
        Self { world, planner }
    }

    pub fn meta(&self) -> Value {
        let (w, p) = (&self.world, &self.planner);
        let (z_min, z_max) = w.dem.min_max();
        json!({
            "name": w.name,
            "source": w.source,
            "width": w.dem.w, "height": w.dem.h, "cell_m": w.dem.cell_m,
            "z_min": z_min, "z_max": z_max,
            "base": [w.base.0, w.base.1],
            "targets": w.targets,
            "beacons": w.beacons,
            "params": p.params,
            "thresholds": {"slope_max_deg": p.thresholds.slope_max_deg, "rough_max_m": p.thresholds.rough_max_m},
            "layers": {
                "slope":    {"unit": "deg", "min": 0, "max": 45},
                "rough":    {"unit": "m",   "min": 0, "max": 1},
                "hazard":   {"unit": "bool"},
                "cost":     {"unit": "rel", "min": 0, "max": 12},
                "pnr":      {"unit": "bool"},
                "coverage": {"unit": "beacons", "min": 0, "max": 6}
            }
        })
    }

    pub fn terrain(&self, step: usize) -> GridBytes {
        let d = self.world.dem.downsample(step.clamp(1, 64));
        GridBytes {
            w: d.w,
            h: d.h,
            cell_m: d.cell_m,
            bytes: d.to_le_bytes(),
        }
    }

    pub fn layer(&self, name: &str, q: &LayerQuery) -> Result<GridBytes, EngineError> {
        let step = q.step.unwrap_or(1).clamp(1, 64);
        let p = &self.planner;
        Ok(match name {
            "slope" => u8_grid(&p.slope, step, 0.0, 45.0),
            "rough" => u8_grid(&p.rough, step, 0.0, 1.0),
            "hazard" => bool_grid(&p.hazard, step),
            "cost" => u8_grid(p.cost(q.mode.unwrap_or(Mode::Balanced)), step, 0.0, 12.0),
            "coverage" => u8_grid(&p.coverage, step, 0.0, 6.0),
            "pnr" => {
                let pos = (q.x.unwrap_or(p.base.0), q.y.unwrap_or(p.base.1));
                let o2 = q.o2_min.unwrap_or(p.params.o2_capacity_min);
                bool_grid(&p.pnr_mask(pos, o2)?, step)
            }
            _ => return Err(EngineError::UnknownLayer(name.to_string())),
        })
    }

    pub fn route(&self, r: &RouteReq) -> Result<Value, EngineError> {
        let route = self.planner.route(
            (r.start[0], r.start[1]),
            (r.goal[0], r.goal[1]),
            r.mode.unwrap_or(Mode::Balanced),
        )?;
        Ok(serde_json::to_value(route).unwrap())
    }

    pub fn compare(&self, r: &RouteReq) -> Result<Value, EngineError> {
        let [a, b, c] = self
            .planner
            .compare((r.start[0], r.start[1]), (r.goal[0], r.goal[1]));
        if let (Err(e), Err(_), Err(_)) = (&a, &b, &c) {
            return Err(e.clone().into());
        }
        Ok(json!({"safe": a.ok(), "balanced": b.ok(), "science": c.ok()}))
    }

    pub fn replan(&self, r: &ReplanReq) -> Result<Value, EngineError> {
        let base = &self.planner;
        let o2 = r.o2_min.unwrap_or(base.params.o2_capacity_min);
        let mode = r.mode.unwrap_or(Mode::Safe);
        let (pos, goal) = ((r.pos[0], r.pos[1]), (r.goal[0], r.goal[1]));
        let out = if r.obstacles.is_empty() {
            base.replan(pos, goal, mode, false, o2)?
        } else {
            base.with_obstacles(&r.obstacles)
                .replan(pos, goal, mode, true, o2)?
        };
        Ok(serde_json::to_value(out).unwrap())
    }

    /// 模擬一次信標定位（量測是用 DEM 模擬的，回應中 `simulated: true`）。
    pub fn localize_sim(&self, r: &SimRequest) -> Value {
        serde_json::to_value(simulate(
            &self.world.dem,
            &self.world.beacons,
            &self.planner.params.nav,
            r,
        ))
        .unwrap()
    }

    pub fn track(&self, r: &TrackReq) -> Result<Value, EngineError> {
        let s = self.planner.track(
            (r.pos[0], r.pos[1]),
            r.sigma_m.unwrap_or(0.0),
            &r.path,
            r.lookahead_m.unwrap_or(25.0),
        )?;
        Ok(serde_json::to_value(s).unwrap())
    }
}
